// Runs the batch script spliced with 7b's manifest (check7b.js's wf-spliced-7b.js) with the
// workflow globals stubbed, through the merged-tree scenarios of the post-mortem's practice.
const fs = require('fs')
const path = require('path')
const S = path.dirname(__filename)
let body = fs.readFileSync(path.join(S, 'out7b/wf-spliced-7b.js'), 'utf8')
body = body.replace(/^const LEDGER_FROM = null/m, 'const LEDGER_FROM = 540').replace(/^const CHECKER_BASE = null/m, 'const CHECKER_BASE = 75')
  .replace(/^export const meta/m, 'const meta')
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
const RUN_OK = { file: 'ProjectFortress/compiler_tests/XXXStub.test', paths: ['ProjectFortress/compiler_tests/XXXStub.test', 'ProjectFortress/compiler_tests/XXXStub.fss'], suite: 'fast-compiler/CompilerJUTest', cases: 1, verdict: 'pass', capture: 'tmp/gate-batch-7b/repair-review-tests/stub.txt' }
const TESTS_ONLY = ['ProjectFortress/compiler_tests/XXXStub.test', 'ProjectFortress/compiler_tests/XXXStub.fss', 'explorations/compile-ladder/climb-batch-7b/REPAIR-review.md']
const repairStub = (paths, runs, answered) => () => ({ landed: true, stopped: false, summary: 'stub', stopsMet: [], forPavol: [], pavolItems: [], headBefore: 'a', headAfter: 'b', pathsChanged: paths, testRuns: runs, failingAnswered: answered || [] })
const review = (x) => () => Object.assign({ approved: true, blockingCode: [], routed: [], fixed: [], pathsOutsideExplorations: [], stopsMet: [], forPavol: [], pavolItems: [], summary: 's' }, x)
const codeOnce = { review: review({ approved: false, blockingCode: ['stub code finding'] }), 'judge:review': () => ({ decision: 'repair', forPavol: [], instructions: ['1. fix'] }) }
const redOnce = { gate: () => ({ green: false, failing: ['XXXStub.test: stub'], countsDown: [], stopped: false }), 'judge:gate': () => ({ decision: 'repair', forPavol: [] }) }
const SCEN = [
  { name: 'every agent approves', over: {}, after: 'gather, gate, review, commit', landed: true },
  { name: 'the review routes a tests-only finding, no judge', over: { review: review({ routed: ['XXXFoo owed; the next batch writes it'] }) }, after: 'gather, gate, review, commit', landed: true, routed: 1 },
  { name: 'a code finding, the judge rules land', over: Object.assign({}, codeOnce, { review: review({ approved: false, blockingCode: ['c'], routed: ['r'] }), 'judge:review': () => ({ decision: 'land', forPavol: [], instructions: ['1. stub step'] }) }), after: 'gather, gate, review, judge:review, commit', landed: true, routed: 2 },
  { name: 'a code finding, its repair changes tests and records only', over: Object.assign({}, codeOnce, { 'repair:review': repairStub(TESTS_ONLY, [RUN_OK]) }), after: 'gather, gate, review, judge:review, repair:review, commit', landed: true, step1a: true },
  { name: 'a code finding, its repair changes a checker source', over: Object.assign({}, codeOnce, { 'repair:review': repairStub(TESTS_ONLY.concat(['ProjectFortress/src/com/sun/fortress/scala_src/typechecker/Stub.scala']), [RUN_OK]) }), after: 'gather, gate, review, judge:review, repair:review, gate:after-review, commit', landed: true },
  { name: 'the gate is red, its repair answers the line with a test', over: Object.assign({}, redOnce, { 'repair:gate': repairStub(TESTS_ONLY, [RUN_OK], [{ failing: 'XXXStub.test: stub', file: RUN_OK.file }]) }), after: 'gather, gate, review, judge:gate, repair:gate, commit', landed: true, step1a: true },
  { name: 'a rung meets a stop nothing lifts: the push is held', over: { 'rung:W': () => ({ landed: true, stopped: false, summary: 's', stopsMet: [{ stop: 'stub', evidence: 'x:1', liftedBy: '' }], forPavol: [], reportText: 'R', recordText: 'r' }) }, after: 'gather, gate, review, commit', landed: false, held: true },
]
async function run(sc) {
  const calls = [], logs = []
  const agent = async (prompt, opts) => {
    const L = opts.label
    calls.push({ label: L, prompt })
    if (sc.over[L]) return sc.over[L]()
    if (/^(rung|resume|repair):/.test(L)) return { landed: true, stopped: false, summary: 'stub', stopsMet: [], forPavol: [], reportText: 'REPORTTEXT-SENTINEL', recordText: 'RECORDTEXT-SENTINEL' }
    if (L.startsWith('judge:')) return { decision: 'stop', forPavol: [], instructions: [] }
    if (L.startsWith('skeptic')) return { approved: true, stopsMet: [], forPavol: [] }
    if (L === 'gather') return { unresolved: false, summary: 'stub', commits: [], conflicts: [], pavolItems: [], pavolUnrouted: [] }
    if (L.startsWith('gate')) return { green: true, failing: [], stopped: false }
    if (L.startsWith('review')) return review({})()
    if (L.startsWith('commit')) return /Do NOT push/.test(prompt) ? { pushed: [] } : { pushed: ['main'] }
    return {}
  }
  const pipeline = async (items, s1, s2) => { const out = []; for (const it of items) { const w = await s1(it); out.push(await s2(w, it)) } return out }
  const result = await new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', body)({ base: 'BASE' }, agent, pipeline, null, (s) => logs.push(String(s)))
  return { result, calls, logs }
}
;(async () => {
  let bad = 0
  for (const sc of SCEN) {
    const { result, calls } = await run(sc)
    const after = calls.map(c => c.label).filter(l => !/^(rung|skeptic|resume|repair:[SCWL]|judge:[SCWL])/.test(l)).join(', ')
    const commit = calls.find(c => c.label === 'commit')
    const probs = []
    if (after !== sc.after) probs.push('agents after the scatter: ' + after + ' (expected ' + sc.after + ')')
    if (!!result.landed !== sc.landed) probs.push('landed ' + result.landed)
    if (sc.routed && !(result.reviewRouted && result.reviewRouted.findings.length === sc.routed)) probs.push('reviewRouted ' + JSON.stringify(result.reviewRouted))
    if (commit && /1a\. The gate below ran/.test(commit.prompt) !== !!sc.step1a) probs.push('step 1a ' + !sc.step1a)
    if (commit && !/4\. Start the two microGPT programs/.test(commit.prompt)) probs.push('no microGPT step')
    if (commit && sc.held && !/5\. Keep every wip\/ worktree/.test(commit.prompt)) probs.push('held: no keep step')
    if (commit && !sc.held && !/git worktree remove --force/.test(commit.prompt)) probs.push('no --force removal')
    for (const c of calls) {
      if (/undefined|\[object Object\]|NaN/.test(c.prompt.replace(/reportText: undefined|recordText: undefined/g, ''))) probs.push(c.label + ' prompt holds undefined/[object Object]/NaN')
      if (c.label.startsWith('skeptic') && /REPORTTEXT-SENTINEL|RECORDTEXT-SENTINEL/.test(c.prompt)) probs.push(c.label + ' carries the worker texts')
    }
    const ids = (result.forPavol || []).map(i => i.id)
    console.log((probs.length ? 'BAD  ' : 'ok   ') + sc.name + ': ' + after + (ids.length ? '; items ' + ids.join(', ') : '') + (probs.length ? '\n     ' + probs.join('\n     ') : ''))
    bad += probs.length
    if (sc === SCEN[0]) {
      fs.mkdirSync(path.join(S, 'prompts'), { recursive: true })
      for (const c of calls) fs.writeFileSync(path.join(S, 'prompts', c.label.replace(/[:]/g, '_') + '.txt'), c.prompt)
    }
  }
  console.log('problems: ' + bad)
})().catch(e => { console.log('THREW', e && e.stack); process.exit(1) })
